import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss;

  Transaction(this.coinName, this.dateTime, this.profitLoss);
}

Map<String, List<double>> calculateAverages(List<Transaction> transactions) {
  Map<String, List<double>> coinProfitLoss = {};

  for (Transaction transaction in transactions) {
    if (coinProfitLoss.containsKey(transaction.coinName)) {
      coinProfitLoss[transaction.coinName].add(transaction.profitLoss);
    } else {
      coinProfitLoss[transaction.coinName] = [transaction.profitLoss];
    }
  }

  return coinProfitLoss;
}

