 Certainly! Here's a JavaScript function that uses regular expressions and string manipulation to swap the positions of the first adjective and the adjective immediately preceding a noun in a sentence:

```javascript
function switchAdjectiveOrder(sentence) {
  const wordList = sentence.split(' '); // Split the sentence into an array of words

  for (let i = 0; i < wordList.length - 2; i++) { // Iterate through the array, excluding the last two elements (noun and article)
    if (isAdjective(wordList[i]) && isNounOrArticle(wordList[i + 1])) { // Check if current word is an adjective and next word is a noun or article
      const temp = wordList[i];
      wordList[i] = wordList[i + 1];
      wordList[i + 1] = temp; // Swap the positions of the words
      break;
    }
  }

  return wordList.join(' ') + '.'; // Rejoin the words into a sentence and add a period at the end
}

function isAdjective(word) { // Helper function to check if a word is an adjective
  return ['beautiful', 'green', 'red', 'happy'].some(adj => word.toLowerCase() === adj);
}

function isNounOrArticle(word) { // Helper function to check if a word is a noun or article
  return ['tree', 'park', 'the', 'a', 'an'].some(nounOrArticle => word.toLowerCase() === nounOrArticle);
}

console.log(switchAdjectiveOrder("Beautiful green trees are in the park.")); // Output: "Green beautiful trees are in the park."
```

This function checks each pair of adjacent words in the input sentence and swaps their positions if one is an adjective and the other is a noun or article. The `isAdjective` and `isNounOrArticle` helper functions use simple lists of common English adjectives, nouns, and articles for quick identification. This solution may not work perfectly for all sentences due to its simplistic approach but

