function determineProtocol(inputData) {
  let protocol;

  if (inputData.protocol) { // If protocol is already provided in the input data
    protocol = inputData.protocol;
  } else {
    if (inputData.sourceIP && inputData.destinationIP) { // Check for IP addresses
      if (isValidIPv6Address(inputData.sourceIP) && isValidIPv6Address(inputData.destinationIP)) { // Both IP addresses are IPv6
        protocol = "IPv6";
      }
      // If no IPv6 check passed, assume HTTP as default
    } else if (inputData.port === 80) { // Check for HTTP port
      protocol = "HTTP";
    } else { // Otherwise, assume UDP
      protocol = "UDP";
    }
  }

  return protocol;
}
function isValidIPv6Address(ipAddress) {
  const validRegex = /^([0-9A-F:]{1,4}){7}[0-9A-F:]{1,4}$/i;
