    try {
      const url = `https://maps.googleapis.com/maps/api/geocode/json?address=${encodeURIComponent(address)}&key=${apiKey}`;
      const options = {muteHttpExceptions: true};
      const response = UrlFetchApp.fetch(url, options);
      const jsonResponse = JSON.parse(response.getContentText());

      if (jsonResponse.status === "OK") {
        const location = jsonResponse.results[0].geometry.location;
        sheet.getRange(i + 1, 2).setValue(location.lat); // Latitude goes in column B.
        sheet.getRange(i + 1, 3).setValue(location.lng); // Longitude goes in column C.
      }
    } catch (e) {
      Logger.log(`Error geocoding ${address}: ${e}`);
    }
  }
}
