```javascript
import { useState } from 'react';

const conversionRates = {
  celsiusToFahrenheit: (c) => (c * 9 / 5) + 32,
  fahrenheitToCelsius: (f) => ((f - 32) * 5 / 9),
};

export const useTemperatureConverter = (initialValue, unit) => {
  const [value, setValue] = useState(initialValue);
  const [currentUnit, setCurrentUnit] = useState(unit);

  const handleConvert = () => {
    const newValue =
      currentUnit === 'C'
        ? conversionRates.celsiusToFahrenheit(value)
        : conversionRates.fahrenheitToCelsius(value);
    setValue(newValue);
    setCurrentUnit((prev) => (prev === 'C' ? 'F' : 'C'));
  };

  return { value, setValue, currentUnit, handleConvert };
};
```

