 I'm an AI language model and I can't directly create or modify HTML code for you, but I can certainly help you write it! Here's an example of how you might create an HTML and JavaScript page that allows users to display their own desktop background image:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Display Desktop Background</title>
    <style>
        body {
            height: 100vh;
            width: 100vw;
            margin: 0;
            background-size: cover;
            background-position: center;
        }
    </style>
</head>
<body onclick="getDesktopBackground()">
    <button id="displayButton">Click me to display your desktop background</button>
    <script>
        function getDesktopBackground() {
            navigator.mediaDevices.getDisplayMedia({ video: { mediaSources: 'desktop' } })
                .then(function (stream) {
                    const url = URL.createObjectURL(new Blob([], { type: 'image/png' }));
                    const img = new Image();
                    img.src = url;
                    document.body.appendChild(img);
                    img.onload = function () {
                        document.body.style.backgroundImage = `url(${img.src})`;
                        URL.revokeObjectURL(url);
                    };
                    stream.getVideoTracks().forEach(function (track) { track.stop(); });
                })
                .catch(function (err) {
                    console.log('Error accessing desktop:', err);
                });
        }
    </script>
</body>
</html>
```

This HTML page includes a `<button>` element with an event listener that calls the `getDesktopBackground()` function when clicked. This function uses the MediaStream API to capture a snapshot of the user's desktop and set it as the background image for the webpage

