 To create a simple toast notification using React and the useContextHook, follow these steps:

First, let's create a custom context provider for managing the toast notifications:

1. Create a new file named `ToastContext.js`:

```javascript
import { createContext, useState } from "react";

export const ToastContext = createContext();

export const ToastProvider = ({ children }) => {
  const [toastMessage, setToastMessage] = useState("");

  const addToast = (message) => {
    setToastMessage(message);
    setTimeout(() => setToastMessage(""), 3000); // Clear message after 3 seconds
  };

  return (
    <ToastContext.Provider value={{ addToast }}>{children}</ToastContext.Provider>
  );
};
```

2. Wrap your application or the components that need to show the toast messages inside the `ToastProvider` component:

```javascript
// index.js or App.js
import React from "react";
import { StrictMode, Suspense } from "react";
import { ToastProvider } from "./ToastContext";
import App from "./App";

function Root() {
  return (
    <ToastProvider>
      <StrictMode>
        <Suspense fallback={<div>Loading...</div>}>
          <App />
        </Suspense>
      </StrictMode>
    </ToastProvider>
  );
}

export default Root;
```

3. Create a custom toast component:

```javascript
// Toast.js
import React from "react";
import { useContext } from "react";
import { ToastContext } from "../ToastContext";

const Toast = () => {
  const { addToast } = useContext(ToastContext);

  const handleClick = () => addToast("Hello, this is a test toast message!");

  return (
    <button onClick={handleClick}>
      Show Toast
    </button>
  );
};

export default Toast;
```

