          Math.pow(planet.position[1] - planets[i].position[1], 2) +
          Math.pow(planet.position[2] - planets[i].position[2], 2)
      );

      if (distance < minDistance) {
        tooClose = true;
        break;
      }
    }

    if (!tooClose) {
      planets.push(planet);
    }
  }

  return planets;
}
```

