using namespace std;
void generatePermutations(string str, vector<string>& perms) {
    if (str.length() == 0) {
        perms.push_back("");
        return;
    }
    char firstChar = str[0];
    string remStr = str.substr(1);
    vector<string> tempPerms;
    generatePermutations(remStr, tempPerms);
    for (auto perm : tempPerms) {
        for (int i = 0; i <= perm.size(); ++i) {
            swap(perm[i], perm[0]);
            string newPerm = perm.substr(1);
            perms.push_back(firstChar + newPerm);
            swap(perm[i], perm[0]); // back to original state
        }
    }
    for (auto perm : tempPerms) {
        perms.push_back(firstChar + perm);
