 Here's an example implementation of the `RedisClient` class in Node.js using the `redis` package:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => console.error(`Error connecting to Redis: ${err}`));
  }

  isAlive() {
    return this.client.connected;
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, result) => {
        if (err) return reject(err);
        resolve(result);
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) return reject(err);
        resolve(reply);
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, result) => {
        if (err) return reject(err);
        resolve(result);
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

This class defines the `RedisClient` with the required methods: `constructor`, `isAlive`, `get`, `set`, and `del`. The constructor initializes the Redis client and sets up an error handler. The methods `get`, `set`, and `del` are asynchronous and use promises. The `isAlive` method simply checks if the connection is established by accessing the `connected` property of the Redis client instance. Finally, an instance of `RedisClient` named `redisClient` is created and exported from the module.

